import { useState } from 'react';
import { continueRender, delayRender } from 'remotion';
import './fonts/fonts.css';

/**
 * The one place that loads fonts for every project (text clips, subtitles, custom components).
 * fonts.css (generated by scripts/fetch-fonts.mjs, files in the repo — no internet needed) holds
 * Vietnamese-capable fonts, and registers Georgia / Arial / Times New Roman / Impact / Courier New
 * as look-alikes with full Vietnamese coverage. Otherwise the browser takes "ồ", "ữ"… from another
 * font when the system font is missing or incomplete and the word breaks apart ("Đồ ng").
 */
export const VN_SANS = '"Be Vietnam Pro", Inter, Arial, sans-serif';
export const VN_SERIF = '"Playfair Display", Georgia, serif';
export const VN_HAND = '"Patrick Hand", "Itim", "Comic Sans MS", cursive';
export const VN_MARKER = '"Itim", "Patrick Hand", "Comic Sans MS", cursive';

const FACES = [
  'Be Vietnam Pro', 'Inter', 'Montserrat', 'Playfair Display', 'Patrick Hand', 'Itim',
  'Georgia', 'Arial', 'Helvetica', 'Times New Roman', 'Times', 'Impact', 'Courier New', 'Courier', 'VN Mono',
];
const SAMPLE = 'Aa Đồng ữ Ầ ặ ỗ';

let ready: Promise<unknown> | null = null;
const loadAll = () => (ready ??= Promise.race([
  Promise.all(FACES.flatMap((n) => [`400 40px "${n}"`, `700 40px "${n}"`]).map((f) => document.fonts.load(f, SAMPLE))),
  new Promise((r) => setTimeout(r, 8000)),
]));

const hold = (label: string) => {
  if (typeof document === 'undefined') return;
  try {
    const h = delayRender(label);
    loadAll().then(() => continueRender(h), () => continueRender(h));
  } catch {
    loadAll().catch(() => {}); // outside a Remotion context
  }
};

// Hold the render at import time, so plain text clips get the fonts on the first frame too.
hold('Loading Vietnamese fonts');

/** For components: hold the frame until the fonts are loaded. */
export const useVnFonts = () => {
  useState(() => hold('Loading Vietnamese fonts'));
};

/** The generic `monospace` keyword can't be replaced by @font-face, so put the Vietnamese mono face first. */
export const vnFontStack = (family?: string) =>
  family && /(^|,)\s*monospace\s*$/.test(family) && !/Courier|VN Mono/.test(family) ? `"VN Mono", ${family}` : family;
